@pytest.mark.parametrize('kind',['straight','acceleration','curve','jitter','wrap']) def test_r2_progressive_long_cubic_reference(kind): t=np.arange(11,dtype=np.float64)*.5 if kind=='jitter': t[1:]+=np.sin(np.arange(1,11))*.009 p=np.stack([10*t,np.zeros(11),np.zeros(11)],-1) if kind in ('acceleration','curve','jitter'): p[:,0]=2*t+t**2+.02*t**3 p[:,1]=np.sin(t*.7)+t**3*.03 p[:,2]=t*.12 if kind=='wrap': p[:,2]=np.arctan2(np.sin(3+t*.3),np.cos(3+t*.3)) # Independent V1 index-domain reference, future nodes only. The explicit # query array does not call a production mapping/interpolation helper. q=np.array([1/18,7/6,7/3,32/9,29/6,37/6,68/9,9.]) times=np.interp(q,np.arange(10),t[1:]) unwrapped=p[1:].copy();unwrapped[:,2]=np.unwrap(unwrapped[:,2]) expected=CubicSpline(t[1:],unwrapped,bc_type='not-a-knot',extrapolate=False)(times) expected[:,2]=np.arctan2(np.sin(expected[:,2]),np.cos(expected[:,2])) actual,valid=long_target(p,t,np.ones(11,bool)) assert valid > np.testing.assert_allclose(actual.numpy(),expected,atol=4e-6,rtol=1e-6)
